-- ============================================================
-- TOPLANCE — corridors, exported from a working database.
--
-- Generated by `npm run corridors:export`. Do not hand-edit: draft
-- with `npm run corridor:draft`, review, then re-export.
--
-- 54 corridors (52 live, 2 in review)
-- 614 requirements
--
-- Safe to re-run: every insert is `on conflict do nothing` on the
-- corridor's natural key, so applying this over a database where
-- someone has already reviewed drafts leaves their decisions alone.
-- It adds corridors; it never edits or removes one.
-- ============================================================

-- ---------- AE · work · v1 · live ----------
with c as (
  insert into corridors (
    nationality_iso, destination_iso, purpose, visa_name, version, effective_from,
    source_name, source_url, processing_weeks_min, processing_weeks_max,
    government_fee_minor, government_fee_currency,
    is_live, last_verified_at, review_state, approved_by, approved_at,
    reject_reason, source_hash
  )
  values ('ng', 'ae', 'work', 'Employment Entry Permit', 1, date '2026-02-01', 'UAE Ministry of Human Resources and Emiratisation', 'https://u.ae/en/information-and-services/visa-and-emirates-id', 2, 5, 110000, 'AED', true, null, 'approved', null, null, null, null)
  on conflict on constraint corridors_corridor_version_key do nothing
  returning id
)
insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('passport', 'International passport (bio page)', 'Minimum six months validity from the date of entry.', 'identity', true, 1, null),
  ('passport_photos', 'Passport photographs ×2', 'White background, taken in the last six months.', 'identity', true, 2, null),
  ('offer_letter', 'Attested employment offer', 'Attested by the UAE embassy in Abuja.', 'sponsorship', true, 3, null),
  ('qualifications', 'Attested degree certificate', 'Attested by the Ministry of Foreign Affairs and the UAE embassy.', 'qualifications', true, 4, null),
  ('medical', 'Medical fitness certificate', 'Completed after arrival, but booked before travel.', 'health', true, 5, null),
  ('police_certificate', 'Police character certificate', 'Issued within the last three months.', 'background', true, 6, null),
  ('birth_certificate', 'Birth certificate', 'Attested if dependants are travelling with you.', 'identity', false, 7, null),
  ('funds', 'Bank statements — 3 months', 'Three full months with a closing balance on every page.', 'financial', false, 8, null),
  ('application_form', 'Completed application form', 'Submitted by your sponsoring employer.', 'forms', true, 9, null)
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

