insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('policy_document_confirmation', 'Confirmation you have read and understood the ‘Policy Document On Non-EEA Family Reunification’', 'Please confirm you have read and understood the ‘Policy Document On Non-EEA Family Reunification’.', 'formality', true, 1, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('passport', 'Original Passport', 'Valid for at least 6 months after the intended date of arrival in Ireland. Must have sufficient space for a visa to be inserted, at least two empty pages. A copy of all stamped or containing visas pages of your passport is required.', 'identity', true, 2, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('previous_passports', 'Previous passports', 'Submit all previous passports. The first page and a copy of all stamped or containing visas pages of your old and new passports are required.', 'travel_history', true, 3, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('residence_permission_where_applying', 'Evidence of your permission to be in the country from where you are applying', 'If you are not a national of the country from where you are applying, submit evidence of your permission to be in that country e.g. a residence card. You must also have at least 3 months permission to be in that country after your intended date of departure from Ireland.', 'residence_status', false, 4, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('online_application_form', 'Fully completed and signed online application form', 'If the applicant is a minor, signature(s) of the legal guardian(s) is required.', 'application', true, 5, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('photographs', 'Two recent photographs', 'Not older than 6 months, 35x45 in colour, preferably biometric type with white background. Write your full name on the back of the photographs submitted with the application.', 'photo', true, 6, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('application_letter', 'Signed letter of application', 'Including your full contact details, in English, outlining your reason for wanting to come to Ireland, providing details of the family member in Ireland who is sponsoring your application, and giving details of any other members of your family who are currently in Ireland, the UK, or any other EU Member State.', 'letter', true, 7, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('sponsor_status_irish_citizen_in_ireland', 'Sponsor status — Irish citizen in Ireland', 'In the case of a sponsor who is an Irish citizen and residing in Ireland, a clear and legible copy of their passport or other documentary evidence attesting to their Irish citizenship.', 'sponsor', false, 8, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('sponsor_status_irish_citizen_abroad', 'Sponsor status — Irish citizen living abroad', 'In the case of a sponsor who is an Irish citizen and residing in a country other than Ireland, a clear and legible copy of their passport showing evidence of their residency in the country in which they are residing.', 'sponsor', false, 9, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('sponsor_status_non_eea', 'Sponsor status — non-EEA sponsor', 'In the case of a sponsor who is a non-EEA citizen: a clear and legible copy of all pages of their passport; where relevant, a copy of their certificate of registration; a copy of their current Employment Permit / Researcher (Scientific) Hosting Agreement or other evidence of eligibility to sponsor.', 'sponsor', false, 10, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('marriage_or_civil_partnership_certificate', 'Marriage certificate or civil partnership certificate', 'For spouse or civil partner. Marriages/civil partnerships must be capable of recognition under Irish law for other purposes outside of the immigration system.', 'relationship', false, 11, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('spouse_relationship_history', 'Relationship history — spouse', 'If your sponsor (spouse/civil partner) is residing in Ireland and you have not resided together since your marriage/civil partnership, provide a full account of your relationship history, including where and when you met evidenced by e.g. visas, entry/exit stamps on the passport of your spouse, photographs, correspondence by e-mail, telephone etc.', 'relationship', false, 12, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('child_birth_certificate_or_adoption_order', 'Birth certificate, adoption order', 'For a child under 18 years and unmarried.', 'relationship', false, 13, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('child_custody_order', 'Evidence that you have been given full custody and access rights to the child i.e. a court order', 'In the case of a child from a previous marriage or relationship.', 'legal', false, 14, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('child_other_parent_affidavit', 'Sworn affidavit by the other parent consenting to the child being removed from their home country', 'In the case of a child from a previous marriage or relationship, where the other parent has some custody or access rights.', 'legal', false, 15, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('minor_travel_consent', 'Written letter of consent from both parents/legal guardians', 'If they are travelling either alone or with a person other than their parent/legal guardian (e.g. an adult relative, nurse).', 'consent', false, 16, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('de_facto_relationship_evidence', 'Evidence that will support the existence and durability of your relationship', 'For a De Facto Partner. Examples given include registration certificate of partnership (if applicable), evidence of common ownership of property, joint tenancy of property, on-going correspondence addressed to both partners at the same address, financial dependence/interdependence or other relevant documentary evidence.', 'relationship', false, 17, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('de_facto_relationship_history', 'Relationship history — de facto partner', 'For a De Facto Partner, including where and when you met evidenced by e.g. visas, entry/exit stamps on the passport of partner, photographs, correspondence by e-mail, telephone etc.', 'relationship', false, 18, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('applicant_bank_statements', 'Detailed statement of your bank accounts', 'Covering a six month period immediately prior to your application.', 'financial', true, 19, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('sponsor_bank_statements', 'Detailed statement of your sponsor’s bank accounts', 'Covering a six month period immediately prior to your application.', 'financial', true, 20, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('sponsor_earnings_ireland_resident', 'Evidence that sponsor meets the minimum level of earnings required', 'In the case of a sponsor who is resident in Ireland: Employment Detail Summary for the 3 years immediately prior to the date of your application; 3 recent consecutive pay slips; or if self-employed, Notices of Assessment of income from self-employment for the three most recent years, and evidence of earnings in the period since the most recent tax return was filed.', 'financial', false, 21, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('projected_earnings_evidence', 'Evidence of projected earnings', 'In the case of a person who is eligible to sponsor applications for immediate family reunification, e.g. copy of contract of employment etc.', 'financial', false, 22, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('sponsor_earnings_after_12_months', 'Evidence that sponsor meets the minimum level of earning required', 'In the case of a person who is eligible to sponsor applications for family reunification after 12 months: Employment Detail Summaries for the previous 2 years (or previous 1 year in the case of an Employment Permit holder who has been in Ireland for 1 year only), or if self-employed, Notices of Assessment of income from self-employment, as appropriate; and 3 recent consecutive pay slips.', 'financial', false, 23, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('employment_permit_holder_contract', 'Copy of contract of employment', 'In the case of an Employment Permit holder, a copy of their contract of employment of at least 1 year from your proposed date of entry giving their annual salary is also required.', 'financial', false, 24, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('family_registration_certificate', 'Detailed family registration certificate', null, 'civil_status', true, 25, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('dependency_evidence', 'Evidence of dependency', 'If you are making your application on the basis of financial and social dependency on your sponsor, provide documentary evidence to establish that you are actually dependent on your sponsor. Evidence normally relevant includes amount, frequency and duration of financial support; any other sources of income; if no other income, why you are unable to work or not eligible for official State benefits; your living costs; details of any other family members in your country of residence; and your medical condition (where relevant), relationship with the sponsor including evidence of active and continuous involvement in your life.', 'financial', false, 26, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('travel_health_insurance', 'Valid travel health insurance', 'Covering any costs of repatriation for medical reasons, emergency medical care and/or emergency hospital care or death during your stay in Ireland. This insurance must be valid for the whole of this territory and must be valid minimum 3 monthly.', 'insurance', true, 27, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('migration_history_statement', 'Migration history statement', 'Including in respect of short term / touristic travel. Include details of migration undertaken with or without the required permissions. Where you have adverse migration history, provide details and documentation.', 'travel_history', true, 28, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('previous_visa_refusals', 'Details of previous visa refusals', 'If you have been refused a visa for any other country, details of this, preferably the original letter issued to you by the authorities of that country, must be submitted.', 'travel_history', false, 29, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('documents_in_english_or_translation', 'Translation of documents not in English', 'If you submit a document that is not in English, it must be accompanied by a full translation. Each translated document must contain confirmation from the translator that it is an accurate translation of the original document, the date of the translation, the translator’s full name and signature, and the translator’s contact details.', 'translation', false, 30, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('original_documents', 'Original documents', 'All documents accompanying your application must be originals.', 'submission', true, 31, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

