  ('return_or_onward_ticket', 'Return ticket or onward journey ticket', 'International travellers should have return ticket or onward journey ticket.', 'travel', true, 4, 'https://indianvisaonline.gov.in/evisa/tvoa.html'),
  ('sufficient_funds', 'Sufficient money to spend during stay in India', 'International travellers should have sufficient money to spend during his/her stay in India.', 'financial', true, 5, 'https://indianvisaonline.gov.in/evisa/tvoa.html'),
  ('separate_passport', 'Separate passport', 'Not available to individuals endorsed on parent''s/spouse''s passport; each individual should have a separate passport.', 'eligibility', true, 6, 'https://indianvisaonline.gov.in/evisa/tvoa.html'),
  ('short_term_course_letter', 'Copy of letter from the institute/organization/hospital etc. concerned on its letter-head', 'For short term courses.', 'supporting_document', false, 7, 'https://indianvisaonline.gov.in/evisa/tvoa.html'),
  ('voluntary_work_letter', 'Copy of letter from the organization concerned on its letter-head', 'For voluntary work of short duration.', 'supporting_document', false, 8, 'https://indianvisaonline.gov.in/evisa/tvoa.html'),
  ('yellow_fever_vaccination_card', 'YELLOW FEVER VACCINATION CARD', 'Nationals of Yellow Fever affected countries or travellers arriving from these countries must carry it at the time of arrival in India, otherwise they may be quarantined for 6 days upon arrival in India.', 'health', false, 9, 'https://indianvisaonline.gov.in/evisa/tvoa.html'),
  ('old_passport_with_eta', 'Old passport on which ETA was issued', 'If travelling on a new passport after ETA was issued on the old passport, the traveler must carry the old passport on which ETA was issued.', 'travel_document', false, 10, 'https://indianvisaonline.gov.in/evisa/tvoa.html'),
  ('copy_of_eta', 'Copy of Electronic Travel Authorization (ETA)', 'Applicant should carry a copy of Electronic Travel Authorization (ETA) along with him/her at the time of travel.', 'travel_document', true, 11, 'https://indianvisaonline.gov.in/evisa/tvoa.html')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

