  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('passport_photo', '1 passport size photograph', '1 passport size photograph with WHITE background (35mm x 45mm).', 'photo', true, 1, 'https://visa.educationmalaysia.gov.my/guidelines/required-documents'),
  ('passport', 'A copy of your Passport', 'Submit your passport data page (bio-data page which shows your face, name etc), all pages with Visa information, and the observation page (showing any extensions, clarifications of name, and previous passport numbers). Empty pages are not required. Passport validity duration must be 18 months and above.', 'identity', true, 2, 'https://visa.educationmalaysia.gov.my/guidelines/required-documents'),
  ('special_pass_or_exit_stamp', 'Special Pass or Exit Stamp', 'Required if applicable.', 'travel_status', false, 3, 'https://visa.educationmalaysia.gov.my/guidelines/required-documents'),
  ('offer_letter', 'Offer Letter', 'A copy of your offer letter is required in order to apply for a student visa in Malaysia. If you are making an online application, you will only be able to fill out the form and submit an application once you have received a letter of acceptance/offer from your university/college.', 'education', true, 4, 'https://visa.educationmalaysia.gov.my/guidelines/required-documents'),
  ('health_declaration_form', 'Health Declaration Form', 'You will be required to fill up and submit a copy of the health declaration form. If making an online application, upload the scanned copy of the form.', 'medical', true, 5, 'https://visa.educationmalaysia.gov.my/guidelines/required-documents'),
  ('academic_certificates_and_transcripts', 'Your academic certificates and transcripts', 'Provide copies of all academic records, certificates or transcripts of studies previously undertaken. Some courses have additional entry requirements; check the entry requirements provided by your educational institution.', 'education', true, 6, 'https://visa.educationmalaysia.gov.my/guidelines/required-documents'),
  ('yellow_fever_vaccination_booklet_card', 'yellow fever vaccination booklet/card', 'Required only if you are coming from a country considered to be at a high risk of yellow fever. You will be asked to provide it before you can clear Immigration at the point of entry.', 'medical', false, 7, 'https://visa.educationmalaysia.gov.my/guidelines/required-documents'),
  ('personal_bond', 'Personal Bond', 'The Immigration Department requires all education institutions in Malaysia to sign a personal bond on behalf of the candidate, binding the University for a specified sum. The institution will require you to lodge the specified amount for this purpose. The personal bond form can be submitted after you have arrived in Malaysia for the student pass endorsement.', 'financial_guarantee', true, 8, 'https://visa.educationmalaysia.gov.my/guidelines/required-documents'),
  ('english_language_certificate', 'English Language Requirement', 'When you apply for a Visa Approval Letter (VAL) you must demonstrate that you have an acceptable level of English language proficiency, and upload the certificate as part of your application. Accepted tests listed on the page are MUET, IELTS/IELTS Online, TOEFL iBT, TOEFL Essentials (Online), PTE Academic/PTE Academic (Online), Cambridge English B1 Preliminary, B2 First, C1 Advanced, C2 Proficiency, Cambridge English - Linguaskill Online, Cambridge English - Occupational English Test (OET) (Conventional/Online), and ELS - Certified Intensive English Programme Level (CIEP Level).', 'language', true, 9, 'https://visa.educationmalaysia.gov.my/guidelines/required-documents')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

