  ('scholarship_proof', 'A document confirming the granting of a national or foreign scholarship.', 'Listed as one of the selectable documents confirming possession of financial resources.', 'finance', false, 12, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('accommodation_proof', 'Written proof of accommodation in Poland for the entire period of validity of the visa, along with the amount of the rental.', 'Applicants who intend to live with family or friends, or who are sponsored by Polish / EU citizens in any other way, are required to submit an invitation registered with appropriate Polish authorities (Urząd Wojewódzki).', 'accommodation', true, 13, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
