  ('proof_of_means', 'Proof that you have enough means of subsistence', 'In the form decided by the mission: a valid bank account statement issued by your bank or balance over the last 3 months, a valid credit card with a certificate of means available, a valid income certificate from your employer for the last three months and salary slips, pension slips, regular income generated by property.', 'financial', true, 9, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('proof_of_accommodation', 'A proof of accommodation', 'For example, an official invitation or a hotel booking or reservation.', 'accommodation', true, 10, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('purpose_of_stay_document', 'A document to confirm the purpose and the conditions of your planned stay in Poland', null, 'purpose', true, 11, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
