  ('delegating_institution_tax_and_incorporation', 'Tax clearance certificate and certificate of business incorporation of institution delegating applicant for visit', null, 'business', true, 14, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('inviting_institution_tax_and_incorporation', 'Copy of tax clearance certificate and certificate of business incorporation of Polish business institution inviting applicant for visit', null, 'business', true, 15, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
