  ('proof_of_previous_business_dealings', 'Proof of previous business dealings with other Polish/Schengen institutions', null, 'business', true, 17, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('conference_fair_seminar_documents', 'For business conferences, fairs, seminars, congresses, etc. – invitation; proof of registration and payment of fees; other documents proving the existence of trade or work relations', null, 'business', false, 18, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
  ('business_financial_documents', 'Documents regarding applicant’s sufficient means of subsistence during intended stay', 'Such as: introduction letter from employer with employer’s consent for travel; salary slips; proof of business ownership; personal/business bank account statements; proof of income generated by property; letter from sponsor and documents regarding sponsor’s financial situation.', 'financial', true, 19, 'https://www.gov.pl/web/nigeria-en/c-type-schengen-visa'),
